    46  //-----------------------------------------------------------------------------
    47  // Auto compute rle_syms / rle_nsyms
    48  static void rle_find_syms(uint8_t *data, uint64_t data_len,
    49                            int64_t *saved, // dim >= 256
    50                            uint8_t *rle_syms, int *rle_nsyms) {
    51      int last = -1, n;
    52      uint64_t i;
    53
    54      if (data_len > 256) {
    55          // 186/450
    56          // Interleaved buffers to avoid cache collisions
    57          int64_t saved2[256+MAGIC] = {0};
    58          int64_t saved3[256+MAGIC] = {0};
    59          int64_t saved4[256+MAGIC] = {0};
    60          int64_t len4 = data_len&~3;
    61          for (i = 0; i < len4; i+=4) {
    62              int d1 = (data[i+0] == last)     <<1;
    63              int d2 = (data[i+1] == data[i+0])<<1;
    64              int d3 = (data[i+2] == data[i+1])<<1;
    65              int d4 = (data[i+3] == data[i+2])<<1;
    66              last = data[i+3];
    67              saved [data[i+0]] += d1-1;
    68              saved2[data[i+1]] += d2-1;
    69              saved3[data[i+2]] += d3-1;
    70              saved4[data[i+3]] += d4-1;
    71          }
    72          while (i < data_len) {
    73              int d = (data[i] == last)<<1;
    74              saved[data[i]] += d - 1;
    75              last = data[i];
    76              i++;
    77          }
    78          for (i = 0; i < 256; i++)
    79              saved[i] += saved2[i] + saved3[i] + saved4[i];
    80      } else {
    81          // 163/391
    82          for (i = 0; i < data_len; i++) {
    83              if (data[i] == last) {
    84                  saved[data[i]]++;
    85              } else {
    86                  saved[data[i]]--;
    87                  last = data[i];
    88              }
    89          }
    90      }
    91
    92      // Map back to a list
    93      for (i = n = 0; i < 256; i++) {
    94          if (saved[i] > 0)
    95              rle_syms[n++] = i;
    96      }
    97      *rle_nsyms = n;
    98  }
