   100  uint8_t *rle_encode(uint8_t *data, uint64_t data_len,
   101                      uint8_t *run,  uint64_t *run_len,
   102                      uint8_t *rle_syms, int *rle_nsyms,
   103                      uint8_t *out, uint64_t *out_len) {
   104      uint64_t i, j, k;
   105      if (!out)
   106          if (!(out = malloc(data_len*2)))
   107              return NULL;
   108
   109      // Two pass:  Firstly compute which symbols are worth using RLE on.
   110      int64_t saved[256+MAGIC] = {0};
   111
   112      if (*rle_nsyms) {
   113          for (i = 0; i < *rle_nsyms; i++)
   114              saved[rle_syms[i]] = 1;
   115      } else {
   116          // Writes back to rle_syms and rle_nsyms
   117          rle_find_syms(data, data_len, saved, rle_syms, rle_nsyms);
   118      }
   119
   120      // 2nd pass: perform RLE itself to out[] and run[] arrays.
   121      for (i = j = k = 0; i < data_len; i++) {
   122          out[k++] = data[i];
   123          if (saved[data[i]] > 0) {
   124              int rlen = i;
   125              int last = data[i];
   126              while (i < data_len && data[i] == last)
   127                  i++;
   128              i--;
   129              rlen = i-rlen;
   130
   131              j += var_put_u32(&run[j], NULL, rlen);
   132          }
   133      }
   134
   135      *run_len = j;
   136      *out_len = k;
   137      return out;
   138  }
