   140  // On input *out_len holds the allocated size of out[].
   141  // On output it holds the used size of out[].
   142  uint8_t *rle_decode(uint8_t *lit, uint64_t lit_len,
   143                      uint8_t *run, uint64_t run_len,
   144                      uint8_t *rle_syms, int rle_nsyms,
   145                      uint8_t *out, uint64_t *out_len) {
   146      uint64_t j;
   147      uint8_t *run_end = run + run_len;
   148
   149  #ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
   150      if (*out_len > 100000)
   151          return NULL;
   152  #endif
   153
   154      int saved[256] = {0};
   155      for (j = 0; j < rle_nsyms; j++)
   156          saved[rle_syms[j]] = 1;
   157
   158      uint8_t *lit_end = lit + lit_len;
   159      uint8_t *out_end = out + *out_len;
   160      uint8_t *outp = out;
   161      while (lit < lit_end) {
   162          if (outp >= out_end)
   163              goto err;
   164
   165          uint8_t b = *lit++;
   166          if (!saved[b]) {
   167              *outp++ = b;
   168          } else {
   169              uint32_t rlen;
   170              run += var_get_u32(run, run_end, &rlen);
   171              if (rlen) {
   172                  if (outp + rlen > out_end)
   173                      goto err;
   174                  memset(outp, b, rlen+1);
   175                  outp += rlen+1;
   176              } else {
   177                  *outp++ = b;
   178              }
   179          }
   180      }
   181
   182      *out_len = outp-out;
   183      return out;
   184
   185   err:
   186      free(out);
   187      return NULL;
   188  }
